class UserPatch(BaseModel):
    name: str | None = None
    email: str | None = None

@app.patch("/users/{user_id}")
async def patch_user(user_id: int, body: UserPatch, db: Db):
    user = await db.get(User, user_id)
    for field, value in body.model_dump().items():
        setattr(user, field, value)
    await db.commit()
    return user

